#[test]
fn different_briefs_get_different_sets_and_the_same_brief_the_same() {
    let game = fake_focus_game();
    let h = harness_with_game(game.path());
    let mut sets = Vec::new();
    for (k, s) in SUBJECTS.iter().enumerate() {
        for mood in ["in winter", "at dawn"] {
            let p = plan(&h, &format!("a{k}_{}", mood.len()), &format!("{s} {mood}"), json!({}));
            let set: BTreeSet<String> = sent(&p).into_iter().collect();
            assert_eq!(set.len(), 4, "{set:?}");
            sets.push(set);
        }
    }
    let overlap = mean_overlap(&sets);
    eprintln!("mean pairwise overlap over {} briefs: {overlap:.3}", sets.len());
    assert!(overlap < 0.25, "references barely vary between briefs: mean overlap {overlap:.3}");
    // determinism: the same request gives the same set and the same plan
    let a = plan(&h, "steel", "a steel gate", json!({}));
    let b = plan(&h, "steel", "a steel gate", json!({}));
    assert_eq!(sent(&a), sent(&b));
    assert_eq!(a.plan_hash, b.plan_hash);
}

#[test]
fn a_generic_brief_never_gets_nation_files_and_a_named_country_may() {
    let game = fake_focus_game();
    let h = harness_with_game(game.path());
    for (k, s) in SUBJECTS.iter().enumerate() {
        let p = plan(&h, &format!("g{k}"), &format!("{s} for a navy"), json!({}));
        for f in sent(&p) {
            assert!(!f.contains("_JAP_") && !f.contains("_GER_"), "{s}: {f}");
        }
        let r = p.style_sources.as_ref().unwrap();
        assert!(r.excluded.iter().any(|e| e.path.contains("focus_JAP_") && e.reason.contains("country tag JAP")), "{:?}", r.excluded);
    }
    // a brief that names Japan may draw Japanese files, and they rank as matches
    let mut japanese = 0;
    for k in 0..10 {
        let p = plan(&h, &format!("j{k}"), &format!("the Japanese imperial navy, variant {k}"), json!({}));
        japanese += sent(&p).iter().filter(|f| f.contains("_JAP_")).count();
        assert!(sent(&p).iter().all(|f| !f.contains("_GER_")));
    }
    assert!(japanese >= 10, "a brief naming Japan should draw Japanese files: {japanese} over 10 plans");
}

#[test]
fn theme_keywords_pull_matching_files() {
    let game = fake_focus_game();
    let h = harness_with_game(game.path());
    for (theme, brief) in [("navy_fleet", "a battleship fleet at sea"), ("air_bomber", "bomber squadrons"), ("industry_factory", "new factories")] {
        let mut hits = 0;
        for k in 0..8 {
            let p = plan(&h, &format!("t{k}"), &format!("{brief}, take {k}"), json!({}));
            hits += sent(&p).iter().filter(|f| f.contains(theme)).count();
            let why: Vec<String> = p.style_sources.as_ref().unwrap().chosen.iter().filter(|c| c.sent_to_provider).map(|c| c.reason.clone()).collect();
            assert!(why.iter().any(|w| w.contains("theme match")), "{why:?}");
        }
        // two of four slots are theme matches; the typical picks may add more
        assert!(hits >= 16, "{theme}: {hits} matching files over 8 plans");
    }
}

#[test]
fn the_style_only_line_goes_with_automatic_references_and_not_with_caller_anchors() {
    let game = fake_focus_game();
    let h = harness_with_game(game.path());
    let auto = plan(&h, "auto", "a steel gate", json!({}));
    assert!(auto.prompt.text.contains("show its style only: never copy their frame, emblem, subject or composition"), "{}", auto.prompt.text);
    assert!(auto.prompt.text.contains("The Hearts of Iron IV national focus icon form"));
    // the caller's own anchors: only they are sent, the line is absent and the form sentence is neutral
    let anchor = "docs/anchor.png";
    std::fs::create_dir_all(h.root().join("docs")).unwrap();
    std::fs::write(h.root().join(anchor), encode_png(&plaque(3)).unwrap()).unwrap();
    let refs = json!({"references": [{"path": anchor, "role": "style_anchor"}]});
    let caller = plan(&h, "caller", "a steel gate", refs.clone());
    assert!(!caller.prompt.text.contains("style only"), "{}", caller.prompt.text);
    assert!(caller.prompt.text.contains(imagegen_core::plan::CALLER_FORM_RULE));
    assert!(!caller.prompt.text.contains("national focus icon form"), "{}", caller.prompt.text);
    assert_eq!(caller.references.len(), 1);
    assert_eq!(caller.references[0].path, anchor);
    assert_eq!(caller.style_selection.as_ref().unwrap().style_mode, Some(imagegen_core::plan::StyleMode::Replace));
    // style_mode add sends the automatic references beside the anchors
    let mut add = refs;
    add["style_mode"] = json!("add");
    let added = plan(&h, "added", "a steel gate", add);
    assert!(added.references.len() > 1, "{:?}", added.references);
    assert_eq!(added.style_selection.as_ref().unwrap().style_mode, Some(imagegen_core::plan::StyleMode::Add));
}

/// A mod with a tier-2 shelf copy, tier-3 assets and a vanilla tier: caller anchors replace every automatic tier.
#[test]
fn a_shelf_of_mostly_national_art_falls_through_to_generic_vanilla_for_a_generic_brief() {
    // the kit's shelf copy holds a few vanilla focus icons, nearly all of one country or region
    let game = fake_focus_game();
    let h = harness_with_game(game.path());
    let shelf = ".claude/skills/hoi4-feature-assets/assets/vanilla_reference/icons/national_focus";
    for (k, name) in
        ["focus_NORDIC_dem_army", "focus_JAP_integrate_the_government", "focus_ITA_blackshirts", "focus_jap_koiso", "focus_generic_tanks"]
            .iter()
            .enumerate()
    {
        let p = h.root().join(format!("{shelf}/{name}.png"));
        std::fs::create_dir_all(p.parent().unwrap()).unwrap();
        std::fs::write(p, encode_png(&plaque(k as u32)).unwrap()).unwrap();
    }
    let p = plan(&h, "tanks", "A column of light tanks rolling through a dusty avenue", json!({}));
    let r = p.style_sources.as_ref().unwrap();
    assert_eq!(r.chosen_tier, Some(4), "the shelf has one generic file, so vanilla is used: {r:#?}");
    let s = sent(&p);
    assert!(!s.is_empty());
    for f in &s {
        let l = f.to_ascii_lowercase();
        assert!(!l.contains("_jap_") && !l.contains("_ger_") && !l.contains("nordic") && !l.contains("_ita_"), "nation file sent: {s:?}");
    }
    let tiers = &r.tiers;
    assert!(tiers.iter().any(|t| t.tier == 2 && t.note.contains("next tier is used")), "{tiers:#?}");
}

#[test]
fn caller_anchors_replace_every_automatic_tier() {
    let game = fake_focus_game();
    let h = harness_with_game(game.path());
    let shelf = ".claude/skills/hoi4-feature-assets/assets/vanilla_reference/icons/national_focus";
    for k in 0..5 {
        let p = h.root().join(format!("{shelf}/focus_jap_shelf_{k}.png"));
        std::fs::create_dir_all(p.parent().unwrap()).unwrap();
        std::fs::write(p, encode_png(&plaque(k)).unwrap()).unwrap();
        let q = h.root().join(format!("gfx/interface/goals/mine/focus_mine_{k}.dds"));
        std::fs::create_dir_all(q.parent().unwrap()).unwrap();
        std::fs::write(q, dds::write_a8r8g8b8(&plaque(k + 20))).unwrap();
    }
    std::fs::create_dir_all(h.root().join("docs")).unwrap();
    let mut refs = Vec::new();
    for k in 0..3 {
        let a = format!("docs/anchor_{k}.png");
        std::fs::write(h.root().join(&a), encode_png(&plaque(40 + k)).unwrap()).unwrap();
        refs.push(json!({"path": a, "role": "style_anchor"}));
    }
    // without anchors, a shelf (tier 2) of only lower-case nation files is skipped for a generic brief, and the
    // mod's own art (tier 3) is used
    let plain = plan(&h, "plain", "a steel gate", json!({}));
    let r = plain.style_sources.as_ref().unwrap();
    assert_eq!(r.chosen_tier, Some(3), "{r:#?}");
    assert!(r.tiers.iter().any(|t| t.tier == 2 && t.note.contains("next tier is used")), "{:#?}", r.tiers);
    let p = plan(&h, "anchored", "a steel gate", json!({"references": refs}));
    assert_eq!(p.references.len(), 3, "only the caller's anchors are sent: {:?}", p.references);
    assert!(p.references.iter().all(|x| x.path.starts_with("docs/anchor_")));
    let r = p.style_sources.as_ref().unwrap();
    for c in &r.chosen {
        assert!(!c.sent_to_provider);
        assert!(c.reason.contains("not sent") || c.reason.starts_with("statistics only"), "{c:?}");
    }
    for t in r.tiers.iter().filter(|t| t.scanned && t.tier > 1) {
        assert!(t.note.contains("nothing sent: the request sends its own style anchors"), "{t:?}");
    }
    assert!(!p.prompt.text.contains("Match the mod") && !p.prompt.text.contains("measured on"), "no measured paragraph: {}", p.prompt.text);
}

#[test]
fn a_near_duplicate_of_an_earlier_output_warns_and_a_different_one_does_not() {
    let h = openai_harness();
    let (_, _, first) = h.make_processed("first_gate", "k1");
    let (_, _, second) = h.make_processed("second_gate", "k2");
    let v = h.validate(&second);
    let findings = v["results"][0]["findings"].as_array().unwrap();
    let near: Vec<&Value> = findings.iter().filter(|f| f["code"] == "GFX-NEAR-DUPLICATE").collect();
    assert_eq!(near.len(), 1, "{findings:#?}");
    assert_eq!(near[0]["level"], "warning");
    assert_eq!(near[0]["evidence"]["earlier"], first.as_str());
    assert_eq!(v["results"][0]["status"], "pass", "a warning never fails validation");
    // the recorded validation carries it
    let rec = h.engine.ledger.entries().unwrap().into_iter().rev().find(|e| e.kind == "validated").unwrap();
    assert!(rec.data["findings"].as_array().unwrap().iter().any(|f| f["code"] == "GFX-NEAR-DUPLICATE"));
    // a different frame and composition: a thin diagonal bar
    let mut bar = Rgba::new(1024, 1024);
    for y in 0..1024u32 {
        for x in 0..1024u32 {
            if (x as i64 - y as i64).abs() < 90 && x > 100 && x < 600 {
                bar.set_px(x, y, [220, 40, 40, 255]);
            }
        }
    }
    h.queue_generation(&encode_png(&bar).unwrap());
    let p = h.plan_focus("third_gate");
    let g = h.engine.generate(serde_json::from_value(json!({"plan_id": p["plan_id"], "idempotency_key": "k3"})).unwrap()).unwrap();
    let cand = g["candidates"][0]["candidate_id"].as_str().unwrap().to_string();
    let proc = h.engine.process(serde_json::from_value(json!({"candidate_id": cand})).unwrap()).unwrap();
    assert!(proc["near_duplicates"].as_array().unwrap().is_empty(), "{:#}", proc["near_duplicates"]);
    let v = h.validate(proc["artifact_id"].as_str().unwrap());
    assert!(!v["results"][0]["findings"].as_array().unwrap().iter().any(|f| f["code"] == "GFX-NEAR-DUPLICATE"), "{v:#}");
    let _ = synthetic_icon_png;
}

#[test]
fn subfamilies_are_inferred_named_limited_and_fall_back() {
    let game = fake_focus_game();
    let h = harness_with_game(game.path());
    let fam = imagegen_core::subfamily::for_family(imagegen_core::family::Family::Focus).expect("focus has sub-families");
    assert!(fam.get("naval").is_some() && fam.get("society").is_some());
    // inferred from the brief: references come only from the naval files
    let p = plan(&h, "fleet", "a battleship fleet at anchor", json!({}));
    let sub = p.subfamily.as_ref().unwrap();
    assert_eq!((sub.id.as_str(), sub.how.as_str(), sub.references_from_subfamily), ("naval", "inferred", true), "{sub:?}");
    assert!(sent(&p).iter().all(|f| f.contains("navy_fleet")), "{:?}", sent(&p));
    assert!(p.prompt.text.contains("Vanilla national focus icon naval files"), "the form note goes into the prompt: {}", p.prompt.text);
    // named in the request, whatever the brief says
    let p = plan(&h, "named", "a quiet harbour town", json!({"subfamily": "air"}));
    assert_eq!(p.subfamily.as_ref().unwrap().how, "named");
    assert!(sent(&p).iter().all(|f| f.contains("air_bomber")), "{:?}", sent(&p));
    let r = p.style_sources.as_ref().unwrap();
    assert!(r.excluded.iter().any(|e| e.reason == "outside the sub-family air"));
    // a sub-family with too few files here falls back to the whole family and says so
    let p = plan(&h, "people", "a crowd of workers", json!({"subfamily": "society"}));
    let sub = p.subfamily.as_ref().unwrap();
    assert!(!sub.references_from_subfamily && sub.note.contains("whole family"), "{sub:?}");
    assert_eq!(sent(&p).len(), 4);
    // a brief that matches no sub-family uses the whole family and says so
    let p = plan(&h, "lake", "a quiet mountain lake", json!({}));
    assert!(p.subfamily.is_none());
    assert!(p.warnings.iter().any(|w| w.contains("points to no sub-family")), "{:?}", p.warnings);
    // an unknown sub-family is refused with the list
    let e = h
        .engine
        .plan(
            serde_json::from_value(
                json!({"family": "focus", "feature_slug": "f", "asset": "x", "brief": "x", "provider": "openai", "subfamily": "pirates"}),
            )
            .unwrap(),
        )
        .unwrap_err();
    assert!(e.to_string().contains("naval"), "{e}");
    // the candidate record keeps the sub-family
    h.queue_edit(&synthetic_icon_png());
    let p = plan(&h, "fleet2", "a battleship fleet at anchor", json!({}));
    h.engine.generate(serde_json::from_value(json!({"plan_id": p.plan_id, "idempotency_key": "k-sub"})).unwrap()).unwrap();
    let rec = h.engine.ledger.entries().unwrap().into_iter().find(|e| e.kind == "generated").unwrap();
    assert_eq!(rec.data["subfamily"], "naval");
    // and hoi4.image_families lists the sub-families
    let f = h.engine.families_info(serde_json::from_value(json!({"family": "focus"})).unwrap()).unwrap();
    let subs = f["family"]["subfamilies"].as_array().unwrap();
    assert!(subs.iter().any(|s| s["id"] == "naval" && s["files"].as_u64().unwrap() > 0 && s["form_note"].is_string()), "{subs:#?}");
}

